func isValidSudoku(board [][]byte) bool {
	cols := make(map[int]map[byte]bool)
	rows := make(map[int]map[byte]bool)
	squares := make(map[[2]int]map[byte]bool) // key = (r /3, c /3)
	for r := 0; r < 9; r++ {
		for c := 0; c < 9; c++ {
			if board[r][c] == '.' {
				continue
			}
			if cols[c] == nil {
				cols[c] = make(map[byte]bool)
			}
			if rows[r] == nil {
				rows[r] = make(map[byte]bool)
			}
			squareKey := [2]int{r / 3, c / 3}
			if squares[squareKey] == nil {
				squares[squareKey] = make(map[byte]bool)
			}
			if cols[c][board[r][c]] || rows[r][board[r][c]] || squares[squareKey][board[r][c]] {
				return false
			}
			cols[c][board[r][c]] = true
			rows[r][board[r][c]] = true
			squares[squareKey][board[r][c]] = true
		}
	}
	return true
}

func twoSum(numbers []int, target int) []int {
	l, r := 0, len(numbers)-1
	for l < r {
		curSum := numbers[l] + numbers[r]
		if curSum > target {
			r--
		} else if curSum < target {
			l++
		} else {
			return []int{l + 1, r + 1}
		}
	}
	return nil
}

func trap(height []int) int {
	if len(height) == 0 {
		return 0
	}
	l, r := 0, len(height)-1
	leftMax, rightMax := height[l], height[r]
	res := 0
	for l < r {
		if leftMax < rightMax {
			l++
			leftMax = max(leftMax, height[l])
			res += leftMax - height[l]
		} else {
			r--
			rightMax = max(rightMax, height[r])
			res += rightMax - height[r]
		}
	}
	return res
}

func checkInclusion(s1 string, s2 string) bool {
	if len(s1) > len(s2) {
		return false
	}
	s1Count, s2Count := [26]int{}, [26]int{}
	for i := 0; i < len(s1); i++ {
		s1Count[s1[i]-'a']++
		s2Count[s2[i]-'a']++
	}
	matches := 0
	for i := 0; i < 26; i++ {
		if s1Count[i] == s2Count[i] {
			matches++
		}
	}
	l := 0
	for r := len(s1); r < len(s2); r++ {
		if matches == 26 {
			return true
		}
		index := s2[r] - 'a'
		s2Count[index]++
		if s1Count[index] == s2Count[index] {
			matches++
		} else if s1Count[index]+1 == s2Count[index] {
			matches--
		}
		index = s2[l] - 'a'
		s2Count[index]--
		if s1Count[index] == s2Count[index] {
			matches++
		} else if s1Count[index]-1 == s2Count[index] {
			matches--
		}
		l++
	}
	return matches == 26
}

func maxSlidingWindow(nums []int, k int) []int {
    output := []int{}
    q := []int{} // indices
    l, r := 0, 0

    for r < len(nums) {
        for len(q) > 0 && nums[q[len(q)-1]] < nums[r] {
            q = q[:len(q)-1]
        }
        q = append(q, r)

        if l > q[0] {
            q = q[1:]
        }

        if r+1 >= k {
            output = append(output, nums[q[0]])
            l++
        }
        r++
    }

    return output
}

