type MinStack struct {
	stack    []int
	minStack []int
}

func Constructor() MinStack {
	return MinStack{
		stack:    []int{},
		minStack: []int{},
	}
}

func (this *MinStack) Push(val int) {
	this.stack = append(this.stack, val)
	if len(this.minStack) == 0 {
		val = val
	} else {
		val = min(val, this.minStack[len(this.minStack)-1])
	}
	this.minStack = append(this.minStack, val)
}

func (this *MinStack) Pop() {
	this.stack = this.stack[:len(this.stack)-1]
	this.minStack = this.minStack[:len(this.minStack)-1]
}

func (this *MinStack) Top() int {
	return this.stack[len(this.stack)-1]
}

func (this *MinStack) GetMin() int {
	return this.minStack[len(this.minStack)-1]
}

func evalRPN(tokens []string) int {
	stack := []int{}
	for _, c := range tokens {
		if c == "+" {
			a := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			b := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			stack = append(stack, a+b)
		} else if c == "-" {
			a := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			b := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			stack = append(stack, b-a)
		} else if c == "*" {
			a := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			b := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			stack = append(stack, a*b)
		} else if c == "/" {
			a := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			b := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			stack = append(stack, b/a)
		} else {
			num, _ := strconv.Atoi(c)
			stack = append(stack, num)
		}
	}
	return stack[0]
}

func dailyTemperatures(temperatures []int) []int {
	res := make([]int, len(temperatures))
	stack := [][]int{}  // pair: [temp, index]

	for i, t := range temperatures {
		for len(stack) > 0 && t > stack[len(stack)-1][0] {
			stackInd := stack[len(stack)-1][1]
			stack = stack[:len(stack)-1]
			res[stackInd] = i - stackInd
		}
		stack = append(stack, []int{t, i})
	}

	return res
}

func carFleet(target int, position []int, speed []int) int {
	pair := make([][]int, len(position))
	for i := range position {
		pair[i] = []int{position[i], speed[i]}
	}

	sort.Slice(pair, func(i, j int) bool {
		return pair[i][0] > pair[j][0]
	})

	stack := []float64{}
	for _, ps := range pair {  // Reverse Sorted Order
		p, s := ps[0], ps[1]
		time := float64(target-p) / float64(s)
		stack = append(stack, time)
		if len(stack) >= 2 && stack[len(stack)-1] <= stack[len(stack)-2] {
			stack = stack[:len(stack)-1]
		}
	}

	return len(stack)
}

func largestRectangleArea(heights []int) int {
	maxArea := 0
	stack := [][]int{}  // pair: (index, height)

	for i, h := range heights {
		start := i
		for len(stack) > 0 && stack[len(stack)-1][1] > h {
			index := stack[len(stack)-1][0]
			height := stack[len(stack)-1][1]
			stack = stack[:len(stack)-1]
			area := height * (i - index)
			if area > maxArea {
				maxArea = area
			}
			start = index
		}
		stack = append(stack, []int{start, h})
	}

	for _, pair := range stack {
		i, h := pair[0], pair[1]
		area := h * (len(heights) - i)
		if area > maxArea {
			maxArea = area
		}
	}

	return maxArea
}

func search(nums []int, target int) int {
	l, r := 0, len(nums)-1

	for l <= r {
		m := l + ((r - l) / 2)  // (l + r) // 2 can lead to overflow
		if nums[m] > target {
			r = m - 1
		} else if nums[m] < target {
			l = m + 1
		} else {
			return m
		}
	}

	return -1
}

func searchMatrix(matrix [][]int, target int) bool {
	ROWS, COLS := len(matrix), len(matrix[0])

	top, bot := 0, ROWS-1
	for top <= bot {
		row := (top + bot) / 2
		if target > matrix[row][COLS-1] {
			top = row + 1
		} else if target < matrix[row][0] {
			bot = row - 1
		} else {
			break
		}
	}

	if !(top <= bot) {
		return false
	}

	row := (top + bot) / 2
	l, r := 0, COLS-1
	for l <= r {
		m := (l + r) / 2
		if target > matrix[row][m] {
			l = m + 1
		} else if target < matrix[row][m] {
			r = m - 1
		} else {
			return true
		}
	}

	return false
}

func minEatingSpeed(piles []int, h int) int {
    l, r := 1, max(piles)
    res := r

    for l <= r {
        k := (l + r) / 2
        totalTime := 0
        for _, p := range piles {
            totalTime += int(math.Ceil(float64(p) / float64(k)))
        }

        if totalTime <= h {
            res = k
            r = k - 1
        } else {
            l = k + 1
        }
    }

    return res
}

func max(piles []int) int {
    maxVal := piles[0]
    for _, val := range piles {
        if val > maxVal {
            maxVal = val
        }
    }
    return maxVal
}

