type TimeMap struct {
	keyStore map[string][][]interface{}  // key : list of [value, timestamp] pairs
}

func Constructor() TimeMap {
	return TimeMap{
		keyStore: make(map[string][][]interface{}),
	}
}

func (this *TimeMap) Set(key string, value string, timestamp int) {
	if _, exists := this.keyStore[key]; !exists {
		this.keyStore[key] = [][]interface{}{}
	}
	this.keyStore[key] = append(this.keyStore[key], []interface{}{value, timestamp})
}

func (this *TimeMap) Get(key string, timestamp int) string {
	res := ""
	values, exists := this.keyStore[key]
	if !exists {
		values = [][]interface{}{}
	}

	l, r := 0, len(values)-1
	for l <= r {
		m := (l + r) / 2
		if values[m][1].(int) <= timestamp {
			res = values[m][0].(string)
			l = m + 1
		} else {
			r = m - 1
		}
	}

	return res
}

func findMedianSortedArrays(nums1 []int, nums2 []int) float64 {
    A, B := nums1, nums2
    total := len(nums1) + len(nums2)
    half := total / 2

    if len(B) < len(A) {
        A, B = B, A
    }

    l, r := 0, len(A)

    for l <= r {
        i := (l + r) / 2
        j := half - i

        Aleft := math.Inf(-1)
        if i > 0 {
            Aleft = float64(A[i-1])
        }

        Aright := math.Inf(1)
        if i < len(A) {
            Aright = float64(A[i])
        }

        Bleft := math.Inf(-1)
        if j > 0 {
            Bleft = float64(B[j-1])
        }

        Bright := math.Inf(1)
        if j < len(B) {
            Bright = float64(B[j])
        }

        if Aleft <= Bright && Bleft <= Aright {
            if total%2 == 1 {
                return math.Min(Aright, Bright)
            }
            return (math.Max(Aleft, Bleft) + math.Min(Aright, Bright)) / 2
        } else if Aleft > Bright {
            r = i - 1
        } else {
            l = i + 1
        }
    }

    return 0
}

