func addTwoNumbers(l1 *ListNode, l2 *ListNode) *ListNode {
    dummy := &ListNode{}
    cur := dummy
    carry := 0

    for l1 != nil || l2 != nil || carry != 0 {
        v1 := 0
        if l1 != nil {
            v1 = l1.Val
        }

        v2 := 0
        if l2 != nil {
            v2 = l2.Val
        }

        // new digit
        val := v1 + v2 + carry
        carry = val / 10
        val = val % 10
        cur.Next = &ListNode{Val: val}

        // update ptrs
        cur = cur.Next
        if l1 != nil {
            l1 = l1.Next
        }
        if l2 != nil {
            l2 = l2.Next
        }
    }

    return dummy.Next
}

