    nums *[]int
}

func (h maxHeap) Len() int           { return len(*h.nums) }
func (h maxHeap) Less(i, j int) bool { return (*h.nums)[i] < (*h.nums)[j] }
func (h maxHeap) Swap(i, j int)      { (*h.nums)[i], (*h.nums)[j] = (*h.nums)[j], (*h.nums)[i] }

