func subsets(nums []int) [][]int {
    res := [][]int{}
    subset := []int{}

    var dfs func(i int)
    dfs = func(i int) {
        if i >= len(nums) {
            temp := make([]int, len(subset))
            copy(temp, subset)
            res = append(res, temp)
            return
        }

        subset = append(subset, nums[i])
        dfs(i + 1)

        subset = subset[:len(subset)-1]
        dfs(i + 1)
    }

    dfs(0)
    return res
}

func combinationSum2(candidates []int, target int) [][]int {
    var res [][]int
    sort.Ints(candidates)

    var dfs func(i int, cur []int, total int)
    dfs = func(i int, cur []int, total int) {
        if total == target {
            tmp := make([]int, len(cur))
            copy(tmp, cur)
            res = append(res, tmp)
            return
        }
        if total > target || i == len(candidates) {
            return
        }

        // include candidates[i]
        cur = append(cur, candidates[i])
        dfs(i+1, cur, total+candidates[i])
        cur = cur[:len(cur)-1]

        // skip duplicates
        for i+1 < len(candidates) && candidates[i] == candidates[i+1] {
            i++
        }
        dfs(i+1, cur, total)
    }

    dfs(0, []int{}, 0)
    return res
}

func permute(nums []int) [][]int {
    if len(nums) == 0 {
        return [][]int{{}}
    }

    perms := permute(nums[1:])
    var res [][]int
    for _, p := range perms {
        for i := 0; i <= len(p); i++ {
            pCopy := append([]int{}, p...)
            pCopy = append(pCopy[:i], append([]int{nums[0]}, pCopy[i:]...)...)
            res = append(res, pCopy)
        }
    }
    return res
}

func subsetsWithDup(nums []int) [][]int {
    res := [][]int{}
    sort.Ints(nums)

    var backtrack func(i int, subset []int)
    backtrack = func(i int, subset []int) {
        if i == len(nums) {
            tmp := make([]int, len(subset))
            copy(tmp, subset)
            res = append(res, tmp)
            return
        }

        subset = append(subset, nums[i])
        backtrack(i+1, subset)
        subset = subset[:len(subset)-1]

        for i+1 < len(nums) && nums[i] == nums[i+1] {
            i++
        }
        backtrack(i+1, subset)
    }

    backtrack(0, []int{})
    return res
}

func generateParenthesis(n int) []string {
	stack := []string{}
	res := []string{}

	var backtrack func(openN, closedN int)
	backtrack = func(openN, closedN int) {
		if openN == n && closedN == n {
			res = append(res, strings.Join(stack, ""))
			return
		}

		if openN < n {
			stack = append(stack, "(")
			backtrack(openN+1, closedN)
			stack = stack[:len(stack)-1]
		}

		if closedN < openN {
			stack = append(stack, ")")
			backtrack(openN, closedN+1)
			stack = stack[:len(stack)-1]
		}
	}

	backtrack(0, 0)
	return res
}

func partition(s string) [][]string {
	res, part := [][]string{}, []string{}
	var dfs func(int)
	dfs = func(i int) {
		if i >= len(s) {
			res = append(res, append([]string{}, part...))
			return
		}
		for j := i; j < len(s); j++ {
			if isPali(s, i, j) {
				part = append(part, s[i:j+1])
				dfs(j + 1)
				part = part[:len(part)-1]
			}
		}
	}
	dfs(0)
	return res
}

func isPali(s string, l, r int) bool {
	for l < r {
		if s[l] != s[r] {
			return false
		}
		l, r = l+1, r-1
	}
	return true
}

func letterCombinations(digits string) []string {
	res := []string{}
	digitToChar := map[string]string{
		"2": "abc",
		"3": "def",
		"4": "ghi",
		"5": "jkl",
		"6": "mno",
		"7": "qprs",
		"8": "tuv",
		"9": "wxyz",
	}

	var backtrack func(int, string)
	backtrack = func(i int, curStr string) {
		if len(curStr) == len(digits) {
			res = append(res, curStr)
			return
		}
		for _, c := range digitToChar[string(digits[i])] {
			backtrack(i+1, curStr+string(c))
		}
	}

	if len(digits) > 0 {
		backtrack(0, "")
	}
	return res
}

func solveNQueens(n int) [][]string {
	col := make(map[int]bool)
	posDiag := make(map[int]bool)
	negDiag := make(map[int]bool)
	res := [][]string{}
	board := make([][]string, n)
	for i := range board {
		board[i] = make([]string, n)
		for j := range board[i] {
			board[i][j] = "."
		}
	}

	var backtrack func(int)
	backtrack = func(r int) {
		if r == n {
			copy := make([]string, n)
			for i := range board {
				copy[i] = strings.Join(board[i], "")
			}
			res = append(res, copy)
			return
		}
		for c := 0; c < n; c++ {
			if col[c] || posDiag[r+c] || negDiag[r-c] {
				continue
			}
			col[c] = true
			posDiag[r+c] = true
			negDiag[r-c] = true
			board[r][c] = "Q"
			backtrack(r + 1)
			delete(col, c)
			delete(posDiag, r+c)
			delete(negDiag, r-c)
			board[r][c] = "."
		}
	}
	backtrack(0)
	return res
}

func maxAreaOfIsland(grid [][]int) int {
    rows, cols := len(grid), len(grid[0])
    visit := make(map[[2]int]bool)

    var dfs func(r, c int) int
    dfs = func(r, c int) int {
        if r < 0 ||
            r == rows ||
            c < 0 ||
            c == cols ||
            grid[r][c] == 0 ||
            visit[[2]int{r, c}] {
            return 0
        }
        visit[[2]int{r, c}] = true
        return 1 + dfs(r+1, c) + dfs(r-1, c) + dfs(r, c+1) + dfs(r, c-1)
    }

    area := 0
    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            area = max(area, dfs(r, c))
        }
    }
    return area
}

func islandsAndTreasure(grid [][]int) {
    rows, cols := len(grid), len(grid[0])
    visit := make(map[[2]int]bool)
    q := [][2]int{}

    addCell := func(r, c int) {
        if r < 0 || c < 0 ||
            r == rows ||
            c == cols ||
            visit[[2]int{r, c}] ||
            grid[r][c] == -1 {
            return
        }
        visit[[2]int{r, c}] = true
        q = append(q, [2]int{r, c})
    }

    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            if grid[r][c] == 0 {
                q = append(q, [2]int{r, c})
                visit[[2]int{r, c}] = true
            }
        }
    }

    dist := 0
    for len(q) > 0 {
        qLen := len(q)
        for i := 0; i < qLen; i++ {
            cell := q[0]
            q = q[1:]
            r, c := cell[0], cell[1]
            grid[r][c] = dist
            addCell(r+1, c)
            addCell(r-1, c)
            addCell(r, c+1)
            addCell(r, c-1)
        }
        dist++
    }
}

func orangesRotting(grid [][]int) int {
    q := [][2]int{}
    fresh := 0
    time := 0

    for r := 0; r < len(grid); r++ {
        for c := 0; c < len(grid[0]); c++ {
            if grid[r][c] == 1 {
                fresh++
            }
            if grid[r][c] == 2 {
                q = append(q, [2]int{r, c})
            }
        }
    }

    directions := [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}
    for fresh > 0 && len(q) > 0 {
        length := len(q)
        for i := 0; i < length; i++ {
            r, c := q[0][0], q[0][1]
            q = q[1:]

            for _, dir := range directions {
                dr, dc := dir[0], dir[1]
                row, col := r+dr, c+dc
                if row >= 0 && row < len(grid) &&
                    col >= 0 && col < len(grid[0]) &&
                    grid[row][col] == 1 {
                    grid[row][col] = 2
                    q = append(q, [2]int{row, col})
                    fresh--
                }
            }
        }
        time++
    }

    if fresh == 0 {
        return time
    }
    return -1
}

func solve(board [][]byte) {
    rows, cols := len(board), len(board[0])

    var capture func(r, c int)
    capture = func(r, c int) {
        if r < 0 || c < 0 || r == rows || c == cols || board[r][c] != 'O' {
            return
        }
        board[r][c] = 'T'
        capture(r+1, c)
        capture(r-1, c)
        capture(r, c+1)
        capture(r, c-1)
    }

    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            if board[r][c] == 'O' && (r == 0 || r == rows-1 || c == 0 || c == cols-1) {
                capture(r, c)
            }
        }
    }

    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            if board[r][c] == 'O' {
                board[r][c] = 'X'
            }
        }
    }

    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            if board[r][c] == 'T' {
                board[r][c] = 'O'
            }
        }
    }
}

func findOrder(numCourses int, prerequisites [][]int) []int {
    prereq := make(map[int][]int)
    for c := 0; c < numCourses; c++ {
        prereq[c] = []int{}
    }
    for _, pre := range prerequisites {
        crs, pre := pre[0], pre[1]
        prereq[crs] = append(prereq[crs], pre)
    }

    output := []int{}
    visit, cycle := make(map[int]bool), make(map[int]bool)

    var dfs func(crs int) bool
    dfs = func(crs int) bool {
        if cycle[crs] {
            return false
        }
        if visit[crs] {
            return true
        }

        cycle[crs] = true
        for _, pre := range prereq[crs] {
            if dfs(pre) == false {
                return false
            }
        }
        delete(cycle, crs)
        visit[crs] = true
        output = append(output, crs)
        return true
    }

    for c := 0; c < numCourses; c++ {
        if dfs(c) == false {
            return []int{}
        }
    }
    return output
}

func findRedundantConnection(edges [][]int) []int {
    par := make([]int, len(edges)+1)
    for i := 0; i < len(par); i++ {
        par[i] = i
    }
    rank := make([]int, len(edges)+1)
    for i := 0; i < len(rank); i++ {
        rank[i] = 1
    }

    var find func(n int) int
    find = func(n int) int {
        p := par[n]
        for p != par[p] {
            par[p] = par[par[p]]
            p = par[p]
        }
        return p
    }

    var union func(n1, n2 int) bool
    union = func(n1, n2 int) bool {
        p1, p2 := find(n1), find(n2)

        if p1 == p2 {
            return false
        }
        if rank[p1] > rank[p2] {
            par[p2] = p1
            rank[p1] += rank[p2]
        } else {
            par[p1] = p2
            rank[p2] += rank[p1]
        }
        return true
    }

    for _, edge := range edges {
        n1, n2 := edge[0], edge[1]
        if !union(n1, n2) {
            return []int{n1, n2}
        }
    }
    return []int{}
}

func ladderLength(beginWord string, endWord string, wordList []string) int {
    endWordExists := false
    for _, word := range wordList {
        if word == endWord {
            endWordExists = true
            break
        }
    }
    if !endWordExists {
        return 0
    }

    nei := make(map[string][]string)
    wordList = append(wordList, beginWord)
    for _, word := range wordList {
        for j := 0; j < len(word); j++ {
            pattern := word[:j] + "*" + word[j+1:]
            nei[pattern] = append(nei[pattern], word)
        }
    }

    visit := make(map[string]bool)
    visit[beginWord] = true
    q := []string{beginWord}
    res := 1

    for len(q) > 0 {
        qLen := len(q)
        for i := 0; i < qLen; i++ {
            word := q[0]
            q = q[1:]

            if word == endWord {
                return res
            }
            for j := 0; j < len(word); j++ {
                pattern := word[:j] + "*" + word[j+1:]
                for _, neiWord := range nei[pattern] {
                    if !visit[neiWord] {
                        visit[neiWord] = true
                        q = append(q, neiWord)
                    }
                }
            }
        }
        res++
    }
    return 0
}

func networkDelayTime(times [][]int, n int, k int) int {
    edges := make(map[int][][2]int)
    for _, time := range times {
        u, v, w := time[0], time[1], time[2]
        edges[u] = append(edges[u], [2]int{v, w})
    }

    minHeap := &MinHeap{}
    heap.Init(minHeap)
    heap.Push(minHeap, [2]int{0, k})
    visit := make(map[int]bool)
    t := 0

    for minHeap.Len() > 0 {
        item := heap.Pop(minHeap).([2]int)
        w1, n1 := item[0], item[1]

        if visit[n1] {
            continue
        }
        visit[n1] = true
        t = w1

        for _, edge := range edges[n1] {
            n2, w2 := edge[0], edge[1]
            if !visit[n2] {
                heap.Push(minHeap, [2]int{w1 + w2, n2})
            }
        }
    }

    if len(visit) == n {
        return t
    }
    return -1
}

type MinHeap [][2]int

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x interface{}) {
	*h = append(*h, x.([2]int))
}

func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

func findItinerary(tickets [][]string) []string {
    adj := make(map[string][]string)
    for _, ticket := range tickets {
        src:= ticket[0]
        adj[src] = []string{}
    }
    res := []string{}

    for _, ticket := range tickets {
        src, dst := ticket[0], ticket[1]
        adj[src] = append(adj[src], dst)
    }

    for key := range adj {
        sort.Strings(adj[key])
    }

    var dfs func(adj map[string][]string, result []string, src string)
    dfs = func(adj map[string][]string, result []string, src string) {
        if destinations, exists := adj[src]; exists {
            destCopy := make([]string, len(destinations))
            copy(destCopy, destinations)

            for len(destCopy) > 0 {
                dest := destCopy[0]
                adj[src] = adj[src][1:]
                dfs(adj, res, dest)
                destCopy = make([]string, len(adj[src]))
                copy(destCopy, adj[src])
            }
        }
        res = append(res, src)
    }

    dfs(adj, res, "JFK")

    for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
        res[i], res[j] = res[j], res[i]
    }

    if len(res) != len(tickets)+1 {
        return []string{}
    }
    return res
}

func minCostConnectPoints(points [][]int) int {
    n := len(points)
    adj := make(map[int][][2]int)
    for i := 0; i < n; i++ {
        adj[i] = [][2]int{}
    }

    for i := 0; i < n; i++ {
        x1, y1 := points[i][0], points[i][1]
        for j := i + 1; j < n; j++ {
            x2, y2 := points[j][0], points[j][1]
            dist := abs(x1-x2) + abs(y1-y2)
            adj[i] = append(adj[i], [2]int{dist, j})
            adj[j] = append(adj[j], [2]int{dist, i})
        }
    }

    res := 0
    visit := make(map[int]bool)
    minH := &MinHeap{}
    heap.Init(minH)
    heap.Push(minH, [2]int{0, 0})

    for len(visit) < n {
        item := heap.Pop(minH).([2]int)
        cost, i := item[0], item[1]

        if visit[i] {
            continue
        }
        res += cost
        visit[i] = true

        for _, neighbor := range adj[i] {
            neiCost, nei := neighbor[0], neighbor[1]
            if !visit[nei] {
                heap.Push(minH, [2]int{neiCost, nei})
            }
        }
    }
    return res
}

