func findCheapestPrice(n int, flights [][]int, src int, dst int, k int) int {
    prices := make([]float64, n)
    for i := 0; i < n; i++ {
        prices[i] = math.Inf(1)
    }
    prices[src] = 0

    for i := 0; i < k+1; i++ {
        tmpPrices := make([]float64, len(prices))
        copy(tmpPrices, prices)

        for _, flight := range flights {
            s, d, p := flight[0], flight[1], flight[2]
            if prices[s] == math.Inf(1) {
                continue
            }
            if prices[s]+float64(p) < tmpPrices[d] {
                tmpPrices[d] = prices[s] + float64(p)
            }
        }
        prices = tmpPrices
    }

    if prices[dst] == math.Inf(1) {
        return -1
    }
    return int(prices[dst])
}

func minCostClimbingStairs(cost []int) int {
    for i := len(cost) - 3; i >= 0; i-- {
        cost[i] += min(cost[i+1], cost[i+2])
    }
    return min(cost[0], cost[1])
}

func canPartition(nums []int) bool {
    sum := 0
    for _, num := range nums {
        sum += num
    }
    if sum%2 != 0 {
        return false
    }

    dp := make(map[int]bool)
    dp[0] = true
    target := sum / 2

    for i := len(nums) - 1; i >= 0; i-- {
        nextDP := make(map[int]bool)
        for t := range dp {
            if (t + nums[i]) == target {
                return true
            }
            nextDP[t+nums[i]] = true
            nextDP[t] = true
        }
        dp = nextDP
    }
    return false
}

func maxProfit(prices []int) int {
    dp := make(map[[2]int]int)

    var dfs func(i int, buying bool) int
    dfs = func(i int, buying bool) int {
        if i >= len(prices) {
            return 0
        }

        buyingInt := 0
        if buying {
            buyingInt = 1
        }
        key := [2]int{i, buyingInt}

        if val, exists := dp[key]; exists {
            return val
        }

        cooldown := dfs(i+1, buying)
        if buying {
            buy := dfs(i+1, !buying) - prices[i]
            dp[key] = max(buy, cooldown)
        } else {
            sell := dfs(i+2, !buying) + prices[i]
            dp[key] = max(sell, cooldown)
        }
        return dp[key]
    }

    return dfs(0, true)
}

func change(amount int, coins []int) int {
    dp := make([]int, amount+1)
    dp[0] = 1

    for i := len(coins) - 1; i >= 0; i-- {
        nextDP := make([]int, amount+1)
        nextDP[0] = 1

        for a := 1; a <= amount; a++ {
            nextDP[a] = dp[a]
            if a-coins[i] >= 0 {
                nextDP[a] += nextDP[a-coins[i]]
            }
        }
        dp = nextDP
    }
    return dp[amount]
}

func findTargetSumWays(nums []int, target int) int {
    dp := make(map[[2]int]int)

    var backtrack func(i, total int) int
    backtrack = func(i, total int) int {
        if i == len(nums) {
            if total == target {
                return 1
            }
            return 0
        }

        key := [2]int{i, total}
        if val, exists := dp[key]; exists {
            return val
        }

        dp[key] = backtrack(i+1, total+nums[i]) + backtrack(i+1, total-nums[i])
        return dp[key]
    }

    return backtrack(0, 0)
}

func isInterleave(s1 string, s2 string, s3 string) bool {
    if len(s1)+len(s2) != len(s3) {
        return false
    }

    dp := make([][]bool, len(s1)+1)
    for i := 0; i <= len(s1); i++ {
        dp[i] = make([]bool, len(s2)+1)
    }
    dp[len(s1)][len(s2)] = true

    for i := len(s1); i >= 0; i-- {
        for j := len(s2); j >= 0; j-- {
            if i < len(s1) && s1[i] == s3[i+j] && dp[i+1][j] {
                dp[i][j] = true
            }
            if j < len(s2) && s2[j] == s3[i+j] && dp[i][j+1] {
                dp[i][j] = true
            }
        }
    }
    return dp[0][0]
}

func longestIncreasingPath(matrix [][]int) int {
    rows, cols := len(matrix), len(matrix[0])
    dp := make(map[[2]int]int)

    var dfs func(r, c, prevVal int) int
    dfs = func(r, c, prevVal int) int {
        if r < 0 || r == rows || c < 0 || c == cols || matrix[r][c] <= prevVal {
            return 0
        }
        if val, exists := dp[[2]int{r, c}]; exists {
            return val
        }

        res := 1
        res = max(res, 1+dfs(r+1, c, matrix[r][c]))
        res = max(res, 1+dfs(r-1, c, matrix[r][c]))
        res = max(res, 1+dfs(r, c+1, matrix[r][c]))
        res = max(res, 1+dfs(r, c-1, matrix[r][c]))
        dp[[2]int{r, c}] = res
        return res
    }

    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            dfs(r, c, -1)
        }
    }

    maxVal := 0
    for _, val := range dp {
        maxVal = max(maxVal, val)
    }
    return maxVal
}

func numDistinct(s string, t string) int {
    cache := make(map[[2]int]int)

    for i := 0; i <= len(s); i++ {
        cache[[2]int{i, len(t)}] = 1
    }
    for j := 0; j < len(t); j++ {
        cache[[2]int{len(s), j}] = 0
    }

    for i := len(s) - 1; i >= 0; i-- {
        for j := len(t) - 1; j >= 0; j-- {
            if s[i] == t[j] {
                cache[[2]int{i, j}] = cache[[2]int{i + 1, j + 1}] + cache[[2]int{i + 1, j}]
            } else {
                cache[[2]int{i, j}] = cache[[2]int{i + 1, j}]
            }
        }
    }
    return cache[[2]int{0, 0}]
}

func minDistance(word1 string, word2 string) int {
    dp := make([][]int, len(word1)+1)
    for i := 0; i <= len(word1); i++ {
        dp[i] = make([]int, len(word2)+1)
        for j := 0; j <= len(word2); j++ {
            dp[i][j] = len(word1) + len(word2)
        }
    }

    for j := 0; j <= len(word2); j++ {
        dp[len(word1)][j] = len(word2) - j
    }
    for i := 0; i <= len(word1); i++ {
        dp[i][len(word2)] = len(word1) - i
    }

    for i := len(word1) - 1; i >= 0; i-- {
        for j := len(word2) - 1; j >= 0; j-- {
            if word1[i] == word2[j] {
                dp[i][j] = dp[i+1][j+1]
            } else {
                dp[i][j] = 1 + min(dp[i+1][j], dp[i][j+1], dp[i+1][j+1])
            }
        }
    }
    return int(dp[0][0])
}

func maxCoins(nums []int) int {
    cache := make(map[[2]int]int)
    nums = append([]int{1}, nums...)
    nums = append(nums, 1)

    for offset := 2; offset < len(nums); offset++ {
        for left := 0; left < len(nums)-offset; left++ {
            right := left + offset
            for pivot := left + 1; pivot < right; pivot++ {
                coins := nums[left] * nums[pivot] * nums[right]
                leftVal := 0
                if val, exists := cache[[2]int{left, pivot}]; exists {
                    leftVal = val
                }
                rightVal := 0
                if val, exists := cache[[2]int{pivot, right}]; exists {
                    rightVal = val
                }
                coins += leftVal + rightVal

                currentMax := 0
                if val, exists := cache[[2]int{left, right}]; exists {
                    currentMax = val
                }
                cache[[2]int{left, right}] = max(coins, currentMax)
            }
        }
    }

    result := 0
    if val, exists := cache[[2]int{0, len(nums) - 1}]; exists {
        result = val
    }
    return result
}

func isMatch(s string, p string) bool {
    cache := make([][]bool, len(s)+1)
    for i := 0; i <= len(s); i++ {
        cache[i] = make([]bool, len(p)+1)
    }
    cache[len(s)][len(p)] = true

    for i := len(s); i >= 0; i-- {
        for j := len(p) - 1; j >= 0; j-- {
            match := i < len(s) && (s[i] == p[j] || p[j] == '.')

            if (j+1) < len(p) && p[j+1] == '*' {
                cache[i][j] = cache[i][j+2]
                if match {
                    cache[i][j] = cache[i+1][j] || cache[i][j]
                }
            } else if match {
                cache[i][j] = cache[i+1][j+1]
            }
        }
    }
    return cache[0][0]
}

func jump(nums []int) int {
    l, r := 0, 0
    res := 0

    for r < (len(nums) - 1) {
        maxJump := 0
        for i := l; i <= r; i++ {
            maxJump = max(maxJump, i+nums[i])
        }
        l = r + 1
        r = maxJump
        res++
    }
    return res
}

func canCompleteCircuit(gas []int, cost []int) int {
    gasSum := 0
    costSum := 0
    for i := 0; i < len(gas); i++ {
        gasSum += gas[i]
        costSum += cost[i]
    }
    if gasSum < costSum {
        return -1
    }

    total := 0
    res := 0
    for i := 0; i < len(gas); i++ {
        total += (gas[i] - cost[i])
        if total < 0 {
            total = 0
            res = i + 1
        }
    }
    return res
}

func isNStraightHand(hand []int, groupSize int) bool {
    if len(hand)%groupSize != 0 {
        return false
    }

    count := make(map[int]int)
    for _, n := range hand {
        count[n]++
    }

    minH := &MinHeap{}
    heap.Init(minH)
    for key := range count {
        heap.Push(minH, key)
    }

    for minH.Len() > 0 {
        first := (*minH)[0]
        for i := first; i < first+groupSize; i++ {
            if _, exists := count[i]; !exists {
                return false
            }
            count[i]--
            if count[i] == 0 {
                if i != (*minH)[0] {
                    return false
                }
                heap.Pop(minH)
            }
        }
    }
    return true
}

