func partitionLabels(s string) []int {
    count := make(map[rune]int)
    res := []int{}
    i, length := 0, len(s)

    for j := 0; j < length; j++ {
        c := rune(s[j])
        count[c] = j
    }

    curLen := 0
    goal := 0
    for i < length {
        c := rune(s[i])
        goal = max(goal, count[c])
        curLen++

        if goal == i {
            res = append(res, curLen)
            curLen = 0
        }
        i++
    }
    return res
}

func checkValidString(s string) bool {
    leftMin, leftMax := 0, 0

    for _, c := range s {
        if c == '(' {
            leftMin, leftMax = leftMin+1, leftMax+1
        } else if c == ')' {
            leftMin, leftMax = leftMin-1, leftMax-1
        } else {
            leftMin, leftMax = leftMin-1, leftMax+1
        }

        if leftMax < 0 {
            return false
        }
        if leftMin < 0 {
            leftMin = 0
        }
    }
    return leftMin == 0
}

func minInterval(intervals [][]int, queries []int) []int {
    sort.Slice(intervals, func(i, j int) bool {
        if intervals[i][0] == intervals[j][0] {
            return intervals[i][1] < intervals[j][1]
        }
        return intervals[i][0] < intervals[j][0]
    })

    sortedQueries := make([]int, len(queries))
    copy(sortedQueries, queries)
    sort.Ints(sortedQueries)

    res := make(map[int]int)
    h := &MinHeap{}
    heap.Init(h)
    i := 0

    for _, q := range sortedQueries {
        for i < len(intervals) && intervals[i][0] <= q {
            l, r := intervals[i][0], intervals[i][1]
            heap.Push(h, []int{r - l + 1, r})
            i++
        }

        for h.Len() > 0 && (*h)[0][1] < q {
            heap.Pop(h)
        }

        if h.Len() > 0 {
            res[q] = (*h)[0][0]
        } else {
            res[q] = -1
        }
    }

    output := make([]int, len(queries))
    for idx, q := range queries {
        output[idx] = res[q]
    }

    return output
}

