func isHappy(n int) bool {
	slow, fast := n, sumSquareDigits(n)

	for slow != fast {
		fast = sumSquareDigits(fast)
		fast = sumSquareDigits(fast)
		slow = sumSquareDigits(slow)
	}

	if fast == 1 {
		return true
	}
	return false
}

func sumSquareDigits(n int) int {
	output := 0
	for n != 0 {
		digit := n % 10
		output += digit * digit
		n = n / 10
	}
	return output
}

func plusOne(digits []int) []int {
	one := 1
	i := 0

	for l, r := 0, len(digits)-1; l < r; l, r = l+1, r-1 {
		digits[l], digits[r] = digits[r], digits[l]
	}

	for one != 0 {
		if i < len(digits) {
			if digits[i] == 9 {
				digits[i] = 0
			} else {
				digits[i] += 1
				one = 0
			}
		} else {
			digits = append(digits, one)
			one = 0
		}
		i++
	}

	for l, r := 0, len(digits)-1; l < r; l, r = l+1, r-1 {
		digits[l], digits[r] = digits[r], digits[l]
	}

	return digits
}

func myPow(x float64, n int) float64 {
	var helper func(float64, int) float64
	helper = func(x float64, n int) float64 {
		if x == 0 {
			return 0
		}
		if n == 0 {
			return 1
		}

		res := helper(x*x, n/2)
		if n%2 != 0 {
			return x * res
		}
		return res
	}

	res := helper(x, abs(n))
	if n >= 0 {
		return res
	}
	return 1 / res
}

