	if n < 0 {
		return -n
	}
	return n
}

func singleNumber(nums []int) int {
	res := 0
	for _, n := range nums {
		res ^= n
	}
	return res
}

func reverse(x int) int {
	const MIN = -2147483648 // -2^31,
	const MAX = 2147483647 //  2^31 - 1

	res := 0
	for x != 0 {
		digit := x % 10
		x /= 10

		if res > MAX/10 || (res == MAX/10 && digit > MAX%10) {
			return 0
		}
		if res < MIN/10 || (res == MIN/10 && digit < MIN%10) {
			return 0
		}

		res = res*10 + digit
	}
	return res
}
